window.BF=window.BF||{};window.BF['4']=[{"id":"j4-1","src":"본문","where":"❶ 웹을 모두에게 열어 두기","en":"If you are right-handed, using a computer mouse or touchscreen with your left hand would be awkward and take a lot of time. However, this is a minor challenge compared to what some of us face on the Internet. For people with certain disabilities, many websites can be nearly impossible to use.","ko":"만약 당신이 오른손잡이라면, 왼손으로 컴퓨터 마우스나 터치스크린을 사용하는 것은 어색하고 시간이 많이 걸릴 것이다. 하지만 이것은 우리 중 일부가 인터넷에서 마주하는 어려움에 비하면 사소한 문제이다. 특정 장애가 있는 사람들에게는 많은 웹 사이트가 거의 사용할 수 없는 것일 수 있다.","v":[{"en":"Few websites are nearly impossible to use, even for people with certain disabilities.","same":false,"ko":"특정 장애가 있는 사람들에게조차 거의 사용할 수 없는 웹 사이트는 거의 없다.","diff":["many websites","Few websites","많은 웹 사이트","웹 사이트가 거의 없음"],"y":"본문 근거: \"For people with certain disabilities, many websites can be nearly impossible to use\" (특정 장애가 있는 사람들에게는 많은 웹 사이트가 거의 사용할 수 없는 것일 수 있다)\n원문은 거의 못 쓰는 사이트가 '많다'고 했는데 바꾼 문장은 그런 사이트가 '거의 없다'고 해서 정반대예요.\n수량 부정어 함정: few(거의 없는)는 a few(몇몇)와 달리 부정의 뜻. nearly impossible이 그대로 있어 같은 말처럼 보이는 게 함정","t":"수량 부정어 함정"},{"en":"For a right-handed person, using the left hand is only a small problem compared to the difficulties some people face online.","same":true,"ko":"오른손잡이에게 왼손을 쓰는 것은 일부 사람들이 온라인에서 겪는 어려움에 비하면 작은 문제일 뿐이다.","sw":[["If you are right-handed","For a right-handed person","당신이 오른손잡이라면 ↔ 오른손잡이에게"],["a minor challenge","a small problem","사소한 어려움 ↔ 작은 문제"],["what some of us face on the Internet","the difficulties some people face online","우리 중 일부가 인터넷에서 마주하는 것 ↔ 일부 사람들이 온라인에서 겪는 어려움"]],"n":"this가 가리키는 내용(오른손잡이의 왼손 사용)을 풀어 써도 같은 내용"},{"en":"Some disabled people may find it almost impossible to use many websites.","same":true,"ko":"일부 장애인들은 많은 웹 사이트를 사용하는 것이 거의 불가능하다고 느낄 수 있다.","sw":[["For people with certain disabilities","Some disabled people","특정 장애가 있는 사람들 ↔ 일부 장애인들"],["nearly impossible to use","almost impossible to use","거의 사용 불가능 ↔ 거의 사용 불가능"]],"n":"사람을 주어로 바꾼 find it ~ to 구조도 같은 내용"},{"en":"Compared to using a mouse with your left hand, what some of us face on the Internet is a minor challenge.","same":false,"ko":"왼손으로 마우스를 쓰는 것에 비하면, 우리 중 일부가 인터넷에서 마주하는 것은 사소한 문제이다.","diff":["this is a minor challenge compared to what some of us face on the Internet","what some of us face on the Internet is a minor challenge","왼손 사용이 사소한 문제","인터넷에서 겪는 어려움이 사소한 문제"],"y":"본문 근거: \"this is a minor challenge compared to what some of us face on the Internet\" (이것은 우리 중 일부가 인터넷에서 마주하는 어려움에 비하면 사소한 문제이다)\n원문은 '왼손 사용'이 사소하다고 했는데 바꾼 문장은 '인터넷에서 겪는 어려움'이 사소하다고 해서 비교 방향이 뒤집혔어요.\n비교 방향 뒤집기: compared to와 minor challenge가 그대로 있어서 무엇이 사소한지 안 따지면 속음","t":"비교 방향 뒤집기"},{"en":"A right-handed person would find it awkward and time-consuming to use a mouse or touchscreen with the left hand.","same":true,"ko":"오른손잡이인 사람은 왼손으로 마우스나 터치스크린을 쓰는 것이 어색하고 시간이 많이 든다고 느낄 것이다.","sw":[["would be awkward and take a lot of time","awkward and time-consuming","어색하고 시간이 많이 걸림 ↔ 어색하고 시간 소모적임"],["If you are right-handed","A right-handed person","오른손잡이라면 ↔ 오른손잡이인 사람"]],"n":"동명사 주어를 find it ~ to 구조로 바꿔도 같은 내용"},{"en":"Although using a mouse with your left hand would feel awkward, it would hardly slow you down.","same":false,"ko":"왼손으로 마우스를 쓰는 것이 어색하게 느껴지겠지만, 그것이 당신을 느리게 만들지는 거의 않을 것이다.","diff":["take a lot of time","it would hardly slow you down","시간이 많이 걸림","거의 느려지지 않음"],"y":"본문 근거: \"using a computer mouse or touchscreen with your left hand would be awkward and take a lot of time\" (왼손으로 컴퓨터 마우스나 터치스크린을 사용하는 것은 어색하고 시간이 많이 걸릴 것이다)\n원문은 어색하고 '시간도 많이 걸린다'고 했는데 바꾼 문장은 '거의 느려지지 않는다'고 해서 달라요.\n일부만 맞는 문장: 앞부분(어색함)은 맞아서 안심하게 됨. hardly는 '거의 ~않는'이라는 부정어라는 점이 포인트","t":"일부만 맞는 문장"}]},{"id":"j4-2","src":"본문","where":"❶ 웹을 모두에게 열어 두기","en":"Web accessibility is the practice of making sure that websites can be used by everyone, including people with disabilities.","ko":"웹 접근성은 장애가 있는 사람들을 포함한 모든 사람이 웹 사이트를 사용할 수 있도록 확실히 하는 실천이다.","v":[{"en":"Web accessibility is the practice of making sure that websites can be used by people with disabilities rather than by everyone.","same":false,"ko":"웹 접근성은 웹 사이트를 모든 사람이 아니라 장애가 있는 사람들이 사용할 수 있도록 확실히 하는 실천이다.","diff":["by everyone, including people with disabilities","by people with disabilities rather than by everyone","장애인을 포함한 모든 사람","모든 사람이 아니라 장애인"],"y":"본문 근거: \"websites can be used by everyone, including people with disabilities\" (장애가 있는 사람들을 포함한 모든 사람이 웹 사이트를 사용할 수 있다)\n원문은 장애인을 '포함한 모든 사람'이라고 했는데 바꾼 문장은 '모든 사람이 아니라 장애인'이라고 해서 범위가 좁아졌어요.\n포함↔대조 바꿔치기: including(포함)이 rather than(~가 아니라)으로 바뀌어도 단어들은 그대로라 같은 말처럼 보임","t":"포함↔대조 바꿔치기"},{"en":"The practice of ensuring that everyone, including people with disabilities, can use websites is called web accessibility.","same":true,"ko":"장애가 있는 사람들을 포함한 모든 사람이 웹 사이트를 사용할 수 있도록 보장하는 실천을 웹 접근성이라고 부른다.","sw":[["websites can be used by everyone","everyone, including people with disabilities, can use websites","웹 사이트가 모두에게 사용될 수 있음 ↔ 모두가 웹 사이트를 사용할 수 있음"],["making sure","ensuring","확실히 하기 ↔ 보장하기"]],"n":"정의 문장의 앞뒤를 바꾸고 수동태를 능동태로 써도 같은 내용"},{"en":"Web accessibility is about ensuring that people with disabilities, as well as everyone else, can use websites.","same":true,"ko":"웹 접근성은 다른 모든 사람뿐만 아니라 장애가 있는 사람들도 웹 사이트를 사용할 수 있도록 보장하는 것이다.","sw":[["everyone, including people with disabilities","people with disabilities, as well as everyone else","장애인을 포함한 모두 ↔ 다른 모든 사람뿐 아니라 장애인도"]],"n":"including A = 나머지 as well as A"},{"en":"Under web accessibility, not all people with disabilities need to be able to use websites.","same":false,"ko":"웹 접근성에서는 장애가 있는 모든 사람이 웹 사이트를 사용할 수 있어야 하는 것은 아니다.","diff":["everyone, including people with disabilities","not all people with disabilities","장애인을 포함한 모든 사람","장애인 모두가 그런 것은 아님"],"y":"본문 근거: \"making sure that websites can be used by everyone, including people with disabilities\" (장애가 있는 사람들을 포함한 모든 사람이 웹 사이트를 사용할 수 있도록 확실히 하는 것)\n원문은 장애인을 포함해 '모든 사람'이 쓸 수 있게 한다고 했는데 바꾼 문장은 장애인 '모두가 그럴 필요는 없다'고 해서 달라요.\n부분부정 함정: not all은 '모두 ~인 것은 아니다'(일부는 제외). all·people with disabilities가 그대로 보여 같은 말로 착각하기 쉬움","t":"부분부정 함정"},{"en":"Web accessibility is the practice of making sure that everyone, including people with disabilities, can take part in building websites.","same":false,"ko":"웹 접근성은 장애가 있는 사람들을 포함한 모든 사람이 웹 사이트를 만드는 일에 참여할 수 있도록 확실히 하는 실천이다.","diff":["websites can be used by everyone","can take part in building websites","모든 사람이 웹 사이트를 '사용'할 수 있음","모든 사람이 웹 사이트를 '만드는 일'에 참여할 수 있음"],"y":"본문 근거: \"websites can be used by everyone, including people with disabilities\" (장애가 있는 사람들을 포함한 모든 사람이 웹 사이트를 사용할 수 있다)\n원문은 모두가 웹 사이트를 '쓸 수 있게' 하는 것인데 바꾼 문장은 모두가 웹 사이트를 '만드는 일'에 참여하게 하는 것이라 달라요.\n역할 바꿈(사용자↔만드는 사람): everyone, including people with disabilities가 그대로라 같은 말 같지만, 그 사람들이 '쓰는 쪽'인지 '만드는 쪽'인지가 바뀜","t":"역할 바꿈(사용자↔만드는 사람)"},{"en":"Web accessibility means making websites usable for all people, and that includes disabled people.","same":true,"ko":"웹 접근성이란 웹 사이트를 모든 사람이 사용할 수 있게 만드는 것을 뜻하며, 여기에는 장애인도 포함된다.","sw":[["can be used by everyone","usable for all people","모두에게 사용될 수 있음 ↔ 모든 사람이 사용할 수 있는"],["including people with disabilities","that includes disabled people","장애인을 포함하여 ↔ 거기에 장애인도 포함됨"]],"n":"can be used = usable, 분사구 including을 절로 풀어도 같은 내용"}]},{"id":"j4-3","src":"본문","where":"❷ 이미지에 대한 텍스트 설명","en":"Sometimes such visual information is important for understanding the text. This is a problem for users with visual disabilities. When they go on a website, they often use programs called “screen readers,” which read online text aloud. However, these programs cannot “read” images.","ko":"때때로 그러한 시각 정보는 글을 이해하는 데 중요하다. 이것은 시각 장애가 있는 사용자들에게 문제가 된다. 그들은 웹 사이트에 접속할 때 흔히 ‘스크린 리더’라고 불리는 프로그램을 사용하는데, 이것은 온라인 텍스트를 소리 내어 읽어 준다. 하지만 이 프로그램들은 이미지를 ‘읽을’ 수 없다.","v":[{"en":"Screen readers read online text aloud, and they can describe images as well.","same":false,"ko":"스크린 리더는 온라인 텍스트를 소리 내어 읽어 주고, 이미지도 설명해 줄 수 있다.","diff":["these programs cannot “read” images","they can describe images as well","이미지를 읽을 수 없음","이미지도 설명할 수 있음"],"y":"본문 근거: \"However, these programs cannot\" (하지만 이 프로그램들은 (이미지를 읽을) 수 없다)\n원문은 스크린 리더가 이미지를 '읽을 수 없다'고 했는데 바꾼 문장은 이미지도 '설명할 수 있다'고 해서 달라요.\n일부만 맞는 문장: 앞부분(텍스트를 소리 내어 읽음)이 정확해서 뒤에 붙은 as well까지 맞다고 믿게 됨","t":"일부만 맞는 문장"},{"en":"Users with visual disabilities often rely on programs that read website text aloud for them.","same":true,"ko":"시각 장애가 있는 사용자들은 웹 사이트의 글을 소리 내어 읽어 주는 프로그램에 흔히 의존한다.","sw":[["they often use programs","often rely on programs","프로그램을 흔히 사용하다 ↔ 프로그램에 흔히 의존하다"]],"n":"use = rely on, 프로그램 이름 대신 하는 일로 설명해도 같은 내용"},{"en":"Because screen readers cannot read images, visual information that helps explain the text can be a problem for visually disabled users.","same":true,"ko":"스크린 리더가 이미지를 읽을 수 없기 때문에, 글을 이해하는 데 도움이 되는 시각 정보는 시각 장애가 있는 사용자에게 문제가 될 수 있다.","sw":[["This is a problem for users with visual disabilities","can be a problem for visually disabled users","시각 장애 사용자에게 문제가 된다 ↔ 시각 장애 사용자에게 문제가 될 수 있다"]],"n":"원인(이미지를 못 읽음)을 Because절로 앞에 내세워도 같은 내용"},{"en":"Screen readers read online text out loud, but they are unable to read images.","same":true,"ko":"스크린 리더는 온라인 텍스트를 소리 내어 읽어 주지만, 이미지는 읽을 수 없다.","sw":[["read online text aloud","read online text out loud","소리 내어 읽다 ↔ 소리 내어 읽다"],["cannot “read” images","unable to read images","이미지를 읽을 수 없음 ↔ 이미지를 읽을 수 없음"]],"n":"which 관계절을 but 문장으로 풀기, cannot = be unable to"},{"en":"Because users with visual disabilities use screen readers, visual information is important for understanding the text.","same":false,"ko":"시각 장애가 있는 사용자들이 스크린 리더를 사용하기 때문에, 시각 정보가 글을 이해하는 데 중요하다.","diff":["Sometimes such visual information is important for understanding the text. This is a problem for users with visual disabilities.","Because users with visual disabilities use screen readers, visual information is important","시각 정보가 중요함 → 그래서 시각 장애인에게 문제","스크린 리더 사용 → 그래서 시각 정보가 중요"],"y":"본문 근거: \"This is a problem for users with visual disabilities\" (이것은 시각 장애가 있는 사용자들에게 문제가 된다)\n원문은 시각 정보가 중요해서 시각 장애인에게 '문제가 된다'는 흐름인데 바꾼 문장은 스크린 리더를 쓰기 '때문에' 시각 정보가 중요하다고 원인과 결과를 뒤집었어요.\n인과 뒤집기: 등장하는 내용이 모두 본문에 있어 맞는 말 같지만 Because가 무엇을 원인으로 삼는지 따져야 함","t":"인과 뒤집기"},{"en":"It is only when visual information is important for understanding the text that screen readers cannot read images.","same":false,"ko":"스크린 리더가 이미지를 읽지 못하는 것은 오직 시각 정보가 글을 이해하는 데 중요할 때뿐이다.","diff":["these programs cannot “read” images","only when visual information is important for understanding the text","(언제나) 이미지를 읽을 수 없음","시각 정보가 중요할 때만 읽을 수 없음"],"y":"본문 근거: \"However, these programs cannot\" (하지만 이 프로그램들은 (이미지를 읽을) 수 없다)\n원문은 스크린 리더가 이미지를 '읽을 수 없다'고 조건 없이 말했는데 바꾼 문장은 시각 정보가 중요할 '때만' 못 읽는다고 해서, 다른 때는 읽을 수 있다는 뜻이 되어 달라요.\nonly when 강조구문(조건 한정): It is ~ that 강조구문 속 only when이 '그때만'이라는 조건을 몰래 붙임. 단어는 전부 본문에 있어 가장 속기 쉬움","t":"only when 강조구문(조건 한정)"}]},{"id":"j4-4","src":"본문","where":"❷ 이미지에 대한 텍스트 설명","en":"Alt text is a brief description of non-textual information. For instance, if an image shows a group of students, its alt text would explain how many students are in the image and what they are doing. Screen readers can detect this alt text and read it aloud.","ko":"대체 텍스트는 텍스트가 아닌 정보에 대한 짧은 설명이다. 예를 들어, 어떤 이미지가 한 무리의 학생들을 보여 준다면, 그 대체 텍스트는 이미지에 학생이 몇 명 있는지와 그들이 무엇을 하고 있는지를 설명할 것이다. 스크린 리더는 이 대체 텍스트를 감지해서 소리 내어 읽어 줄 수 있다.","v":[{"en":"The alt text for a picture of students would tell the number of students and their activity.","same":true,"ko":"학생들이 찍힌 사진의 대체 텍스트는 학생 수와 그들의 활동을 알려 줄 것이다.","sw":[["how many students are in the image","the number of students","이미지 속 학생이 몇 명인지 ↔ 학생 수"],["what they are doing","their activity","그들이 무엇을 하는지 ↔ 그들의 활동"]],"n":"의문사절(how many, what)을 명사구로 바꿔도 같은 내용"},{"en":"Alt text can be found and read out loud by screen readers.","same":true,"ko":"대체 텍스트는 스크린 리더에 의해 감지되어 소리 내어 읽힐 수 있다.","sw":[["can detect","can be found","감지할 수 있다 ↔ 찾아질 수 있다"],["read it aloud","read out loud","소리 내어 읽다 ↔ 소리 내어 읽다"]],"n":"능동태를 수동태로 바꿔도 같은 내용"},{"en":"Alt text would explain what the students are doing, but not how many students are in the image.","same":false,"ko":"대체 텍스트는 학생들이 무엇을 하고 있는지는 설명하겠지만, 이미지에 학생이 몇 명 있는지는 설명하지 않을 것이다.","diff":["how many students are in the image and what they are doing","but not how many students are in the image","학생 수와 하는 일 모두 설명","학생 수는 설명하지 않음"],"y":"본문 근거: \"its alt text would explain how many students are in the image and what they are doing\" (그 대체 텍스트는 이미지에 학생이 몇 명 있는지와 그들이 무엇을 하고 있는지를 설명할 것이다)\n원문은 학생 수와 하는 일을 '둘 다' 설명한다고 했는데 바꾼 문장은 학생 수는 '설명하지 않는다'고 해서 달라요.\n일부만 맞는 문장: A and B 중 하나를 but not으로 빼 버리는 함정. 앞부분이 맞아서 끝까지 안 읽으면 속음","t":"일부만 맞는 문장"},{"en":"Alt text is a brief description that is used only for images of groups of people.","same":false,"ko":"대체 텍스트는 사람들 무리를 담은 이미지에만 쓰이는 짧은 설명이다.","diff":["a brief description of non-textual information","used only for images of groups of people","텍스트가 아닌 정보(전반)에 대한 짧은 설명","사람 무리 이미지에만 쓰임"],"y":"본문 근거: \"Alt text is a brief description of non-textual information\" (대체 텍스트는 텍스트가 아닌 정보에 대한 짧은 설명이다)\n원문의 학생 무리 사진은 For instance(예를 들어)로 든 하나의 예일 뿐인데, 바꾼 문장은 그런 이미지에'만' 쓰인다고 범위를 좁혀서 달라요.\n예시를 정의로 착각(범위 축소): brief description이 그대로 있고 예시 내용도 본문에 있어 맞는 말 같음. For instance 뒤는 예시일 뿐","t":"예시를 정의로 착각(범위 축소)"},{"en":"Screen readers look at an image, write a brief description of it, and then read that description aloud.","same":false,"ko":"스크린 리더는 이미지를 보고 그것에 대한 짧은 설명을 쓴 다음, 그 설명을 소리 내어 읽어 준다.","diff":["Screen readers can detect this alt text","write a brief description of it","스크린 리더는 이미 있는 대체 텍스트를 감지함","스크린 리더가 설명을 직접 씀"],"y":"본문 근거: \"Screen readers can detect this alt text and read it aloud\" (스크린 리더는 이 대체 텍스트를 감지해서 소리 내어 읽어 줄 수 있다)\n원문에서 스크린 리더는 이미 붙어 있는 대체 텍스트를 '찾아서(detect)' 읽을 뿐인데, 바꾼 문장은 스크린 리더가 설명을 '직접 쓴다'고 해서 달라요.\n주체·역할 바꿈: brief description, read aloud가 다 본문 표현이라 맞는 말 같지만, 설명을 '만드는 쪽'과 '읽는 쪽'을 구분해야 잡힘","t":"주체·역할 바꿈"},{"en":"Information that is not in text form can be briefly described by alt text.","same":true,"ko":"텍스트 형태가 아닌 정보는 대체 텍스트로 짧게 설명될 수 있다.","sw":[["a brief description of non-textual information","Information that is not in text form can be briefly described","텍스트가 아닌 정보에 대한 짧은 설명 ↔ 텍스트 형태가 아닌 정보가 짧게 설명될 수 있음"]],"n":"명사 description을 동사 described(수동태)로 바꿔도 같은 내용"}]},{"id":"j4-5","src":"본문","where":"❸ 멀티미디어 콘텐츠를 위한 대본과 자막","en":"In some cases, audio content cannot be accessed or understood. Some people may have hearing disabilities, while others might be in places where they can’t listen to audio, such as a quiet library. Therefore, accessible websites often offer other ways to access information that is presented in audio form.","ko":"어떤 경우에는 음성 콘텐츠에 접근하거나 그것을 이해할 수 없다. 어떤 사람들은 청각 장애가 있을 수 있고, 다른 사람들은 조용한 도서관처럼 음성을 들을 수 없는 장소에 있을 수도 있다. 그래서 접근성 있는 웹 사이트는 흔히 음성 형태로 제시되는 정보에 접근할 수 있는 다른 방법을 제공한다.","v":[{"en":"Since audio content is not always accessible to everyone, accessible websites often provide other ways to get audio information.","same":true,"ko":"음성 콘텐츠는 모든 사람이 항상 접근할 수 있는 것은 아니기 때문에, 접근성 있는 웹 사이트는 흔히 음성 정보를 얻을 다른 방법을 제공한다.","sw":[["Therefore","Since","그러므로 ↔ ~ 때문에"],["offer other ways","provide other ways","다른 방법을 제공하다 ↔ 다른 방법을 제공하다"]],"n":"결과 연결어 Therefore를 원인 접속사 Since로 바꿔도 같은 내용"},{"en":"Only for people with hearing disabilities is audio content difficult to access.","same":false,"ko":"오직 청각 장애가 있는 사람들에게만 음성 콘텐츠가 접근하기 어렵다.","diff":["while others might be in places where they can’t listen to audio","Only for people with hearing disabilities","다른 사람들(조용한 도서관 등)도 못 들을 수 있음","청각 장애인에게만 어려움"],"y":"본문 근거: \"others might be in places where they can’t listen to audio, such as a quiet library\" (다른 사람들은 조용한 도서관처럼 음성을 들을 수 없는 장소에 있을 수도 있다)\n원문은 청각 장애인뿐 아니라 조용한 도서관에 있는 '다른 사람들'도 음성을 못 들을 수 있다고 했는데 바꾼 문장은 청각 장애인'만' 어렵다고 해서 달라요.\nOnly 도치(범위 한정): Only + 부사구가 앞으로 나가 is가 도치된 문장. 문장이 낯설어 해석에 신경 쓰다 보면 only가 잘라 낸 범위를 놓침","t":"Only 도치(범위 한정)"},{"en":"A quiet library is an example of a place where listening to audio is not possible.","same":true,"ko":"조용한 도서관은 음성을 듣는 것이 불가능한 장소의 한 예이다.","sw":[["where they can’t listen to audio","where listening to audio is not possible","음성을 들을 수 없는 곳 ↔ 음성을 듣는 것이 불가능한 곳"]],"n":"such as 예시를 an example of 문장으로 풀어도 같은 내용"},{"en":"Not only people with hearing disabilities but also people in places like a quiet library may be unable to listen to audio.","same":true,"ko":"청각 장애가 있는 사람들뿐만 아니라 조용한 도서관 같은 장소에 있는 사람들도 음성을 듣지 못할 수 있다.","sw":[["Some people may have hearing disabilities","people with hearing disabilities","청각 장애가 있을 수 있는 사람들 ↔ 청각 장애가 있는 사람들"],["such as a quiet library","places like a quiet library","조용한 도서관 같은 ↔ 조용한 도서관 같은 장소"]],"n":"while로 나눈 두 경우를 not only A but also B로 묶어도 같은 내용"},{"en":"Audio content sometimes cannot be understood because the information in it is too difficult for listeners.","same":false,"ko":"음성 콘텐츠는 그 안의 정보가 듣는 사람에게 너무 어렵기 때문에 때때로 이해될 수 없다.","diff":["Some people may have hearing disabilities, while others might be in places where they can’t listen to audio","because the information in it is too difficult for listeners","청각 장애가 있거나, 음성을 들을 수 없는 장소에 있어서","정보 자체가 너무 어려워서"],"y":"본문 근거: \"Some people may have hearing disabilities, while others might be in places where they can’t listen to audio\" (어떤 사람들은 청각 장애가 있을 수 있고, 다른 사람들은 음성을 들을 수 없는 장소에 있을 수도 있다)\n원문이 든 이유는 청각 장애와 들을 수 없는 장소 두 가지인데, 바꾼 문장은 내용이 '너무 어려워서'라고 이유를 바꿔서 달라요.\n원인 바꿈: 첫 문장의 cannot be accessed or understood(이해할 수 없다)와 겹쳐 그럴듯하지만, 본문이 말한 이유가 무엇인지 확인해야 함","t":"원인 바꿈"},{"en":"Accessible websites often offer audio as another way to access information that is presented in other forms.","same":false,"ko":"접근성 있는 웹 사이트는 흔히 다른 형태로 제시되는 정보에 접근하는 또 하나의 방법으로 음성을 제공한다.","diff":["other ways to access information that is presented in audio form","audio as another way to access information that is presented in other forms","음성 정보를 대신할 다른 방법을 제공","다른 형태의 정보를 대신할 방법으로 음성을 제공"],"y":"본문 근거: \"accessible websites often offer other ways to access information that is presented in audio form\" (접근성 있는 웹 사이트는 흔히 음성 형태로 제시되는 정보에 접근할 수 있는 다른 방법을 제공한다)\n원문은 '음성 정보'를 대신할 다른 방법을 준다는 건데, 바꾼 문장은 거꾸로 다른 형태의 정보를 대신할 방법으로 '음성'을 준다고 해서 달라요.\n대체 방향 뒤집기: offer, other ways, audio, presented가 다 들어 있어 같은 말 같지만, 무엇이 무엇을 대신하는지 방향이 뒤바뀜","t":"대체 방향 뒤집기"}]},{"id":"j4-6","src":"본문","where":"❸ 멀티미디어 콘텐츠를 위한 대본과 자막","en":"Transcripts are text versions of the entire audio content, while captions are text versions of the audio that appear in a video as it plays. Captions include not only the text version of the spoken words but also descriptions of the music and other sounds in the video.","ko":"대본은 음성 콘텐츠 전체를 글로 옮긴 것인 반면, 자막은 영상이 재생될 때 영상 속에 나타나는 음성의 텍스트 버전이다. 자막에는 말소리를 글로 옮긴 것뿐만 아니라 영상 속 음악과 다른 소리에 대한 설명도 들어 있다.","v":[{"en":"In a transcript, the whole audio content is turned into text.","same":true,"ko":"대본에서는 음성 콘텐츠 전체가 글로 바뀐다.","sw":[["the entire audio content","the whole audio content","음성 콘텐츠 전체 ↔ 음성 콘텐츠 전체"],["text versions of","turned into text","~의 텍스트 버전 ↔ 글로 바뀐"]],"n":"정의 문장을 수동태 설명으로 바꿔도 같은 내용"},{"en":"In addition to the spoken words, captions also describe the music and other sounds in the video.","same":true,"ko":"말소리에 더하여, 자막은 영상 속 음악과 다른 소리도 설명한다.","sw":[["not only the text version of the spoken words but also","In addition to the spoken words","~뿐만 아니라 ~도 ↔ ~에 더하여"],["descriptions of the music","describe the music","음악에 대한 설명 ↔ 음악을 설명하다"]],"n":"not only A but also B = In addition to A, B"},{"en":"Captions show the audio as text while a video is playing, whereas transcripts turn all of the audio content into text.","same":true,"ko":"자막은 영상이 재생되는 동안 음성을 글로 보여 주는 반면, 대본은 음성 콘텐츠 전부를 글로 바꾼다.","sw":[["as it plays","while a video is playing","영상이 재생될 때 ↔ 영상이 재생되는 동안"],["the entire audio content","all of the audio content","음성 콘텐츠 전체 ↔ 음성 콘텐츠 전부"]],"n":"while 대조의 앞뒤 순서를 바꿔도 같은 내용"},{"en":"It is transcripts, not captions, that appear in a video as it plays.","same":false,"ko":"영상이 재생될 때 영상 속에 나타나는 것은 자막이 아니라 대본이다.","diff":["captions are text versions of the audio that appear in a video as it plays","It is transcripts, not captions, that appear in a video","영상 속에 나타나는 것은 자막","영상 속에 나타나는 것은 대본"],"y":"본문 근거: \"captions are text versions of the audio that appear in a video as it plays\" (자막은 영상이 재생될 때 영상 속에 나타나는 음성의 텍스트 버전이다)\n원문은 영상이 재생될 때 나타나는 것이 '자막'이라고 했는데 바꾼 문장은 자막이 아니라 '대본'이라고 해서 달라요.\n강조구문 주체 바꿈: It is ~ that 강조구문으로 A, not B를 뒤바꿈. while로 비교된 두 개념이 비슷해서 헷갈리기 쉬움","t":"강조구문 주체 바꿈"},{"en":"Captions include the text version of the spoken words rather than descriptions of the music and other sounds.","same":false,"ko":"자막에는 음악과 다른 소리에 대한 설명이 아니라 말소리를 글로 옮긴 것이 들어 있다.","diff":["not only the text version of the spoken words but also descriptions of the music and other sounds","rather than descriptions of the music and other sounds","말소리뿐만 아니라 음악·소리 설명도","음악·소리 설명이 아니라 말소리"],"y":"본문 근거: \"Captions include not only the text version of the spoken words but also descriptions of the music and other sounds in the video\" (자막에는 말소리를 글로 옮긴 것뿐만 아니라 영상 속 음악과 다른 소리에 대한 설명도 들어 있다)\n원문은 말소리와 음악·소리 설명이 '둘 다' 들어 있다고 했는데 바꾼 문장은 음악·소리 설명이 '아니라' 말소리만 들어 있다고 해서 달라요.\nnot only A but also B → A rather than B: 두 표현이 같은 단어를 같은 순서로 써서, 연결어만 바뀐 걸 놓치기 쉬움","t":"not only A but also B → A rather than B"},{"en":"Not all of the audio content is turned into text in a transcript.","same":false,"ko":"대본에서 음성 콘텐츠가 모두 글로 옮겨지는 것은 아니다.","diff":["the entire audio content","Not all of the audio content","음성 콘텐츠 전체","음성 콘텐츠가 모두 그런 것은 아님"],"y":"본문 근거: \"Transcripts are text versions of the entire audio content\" (대본은 음성 콘텐츠 전체를 글로 옮긴 것이다)\n원문은 대본이 음성 '전체'를 글로 옮긴 것이라고 했는데 바꾼 문장은 '모두 옮겨지는 것은 아니다'라고 해서 달라요.\n부분부정 함정: Not all은 '일부는 안 옮겨진다'는 뜻. all이 보여서 entire와 같은 말로 착각하기 쉬움","t":"부분부정 함정"}]},{"id":"j4-7","src":"본문","where":"❹ 보고 듣기에 쉬운 콘텐츠","en":"Having a visual disability doesn’t necessarily mean a person can’t see at all. Some people, including many elderly people, simply have poor eyesight. This makes it difficult for them to read. For this reason, accessible websites have a background color that contrasts with the color of their text. This makes the text clear enough for most people to see.","ko":"시각 장애가 있다는 것이 반드시 앞을 전혀 보지 못한다는 뜻은 아니다. 많은 노인들을 포함한 어떤 사람들은 그저 시력이 나쁠 뿐이다. 이것 때문에 그들은 글을 읽기 어렵다. 이런 이유로, 접근성 있는 웹 사이트는 글자 색과 대비되는 배경색을 쓴다. 이것은 글자를 대부분의 사람들이 볼 수 있을 만큼 선명하게 해 준다.","v":[{"en":"The contrasting colors make the text clear enough for anyone to see, regardless of eyesight.","same":false,"ko":"대비되는 색은 시력과 관계없이 누구나 볼 수 있을 만큼 글자를 선명하게 해 준다.","diff":["most people","anyone to see, regardless of eyesight","대부분의 사람들","시력과 관계없이 누구나"],"y":"본문 근거: \"This makes the text clear enough for most people to see\" (이것은 글자를 대부분의 사람들이 볼 수 있을 만큼 선명하게 해 준다)\n원문은 '대부분의' 사람이 볼 수 있다고 했는데 바꾼 문장은 시력과 관계없이 '누구나' 볼 수 있다고 해서 범위가 넓어졌어요.\n범위 과장: clear enough ~ to see 구조가 그대로라 같은 말처럼 보임. most가 anyone으로 넓어진 걸 잡아야 함","t":"범위 과장"},{"en":"Because some people have poor eyesight, accessible websites use background colors that stand out against the text color.","same":true,"ko":"어떤 사람들은 시력이 나쁘기 때문에, 접근성 있는 웹 사이트는 글자 색과 대비되어 두드러지는 배경색을 쓴다.","sw":[["For this reason","Because","이런 이유로 ↔ ~ 때문에"],["contrasts with the color of their text","stand out against the text color","글자 색과 대비되다 ↔ 글자 색에 대비되어 두드러지다"]],"n":"For this reason을 Because절로 바꿔 원인을 앞에 써도 같은 내용"},{"en":"Accessible websites use a background color that contrasts with the color of their text in order to protect the eyesight of elderly people.","same":false,"ko":"접근성 있는 웹 사이트는 노인들의 시력을 보호하기 위해 글자 색과 대비되는 배경색을 쓴다.","diff":["This makes the text clear enough for most people to see","in order to protect the eyesight of elderly people","글자를 대부분의 사람이 볼 수 있게 선명하게 하려고","노인들의 시력을 보호하려고"],"y":"본문 근거: \"This makes the text clear enough for most people to see\" (이것은 글자를 대부분의 사람들이 볼 수 있을 만큼 선명하게 해 준다)\n원문에서 대비되는 배경색은 시력이 나쁜 사람도 글자를 '잘 읽도록' 하려는 것이지, 시력을 '보호'하려는 게 아니라서 달라요.\n이유·목적 혼동: elderly people, eyesight, contrasts가 다 본문 단어라 맞는 말 같지만, 본문이 말한 목적(글자를 선명하게)과 비교해야 잡힘","t":"이유·목적 혼동"},{"en":"Not all people with visual disabilities are completely unable to see.","same":true,"ko":"시각 장애가 있는 모든 사람이 앞을 전혀 볼 수 없는 것은 아니다.","sw":[["doesn’t necessarily mean","Not all","반드시 ~인 것은 아니다 ↔ 모두가 ~인 것은 아니다"],["can’t see at all","completely unable to see","전혀 보지 못하다 ↔ 완전히 볼 수 없다"]],"n":"부분 부정: not necessarily = not all"},{"en":"Many elderly people have poor eyesight, which makes reading difficult for them.","same":true,"ko":"많은 노인들은 시력이 나쁜데, 이것은 그들이 글을 읽기 어렵게 만든다.","sw":[["including many elderly people","Many elderly people","많은 노인들을 포함한 ↔ 많은 노인들"],["This makes it difficult for them to read","which makes reading difficult for them","이것이 그들이 읽기 어렵게 만든다 ↔ 이는 그들에게 읽기를 어렵게 만든다"]],"n":"두 문장을 관계사 which로 이어도 같은 내용"},{"en":"Accessible websites use contrasting colors mainly for people who cannot see at all, not for those with poor eyesight.","same":false,"ko":"접근성 있는 웹 사이트는 시력이 나쁜 사람들이 아니라 주로 앞을 전혀 보지 못하는 사람들을 위해 대비되는 색을 쓴다.","diff":["For this reason, accessible websites have a background color","mainly for people who cannot see at all, not for those with poor eyesight","시력이 나쁜 사람들 때문에(이런 이유로) 대비 색 사용","시력이 나쁜 사람이 아니라 전혀 못 보는 사람을 위해"],"y":"본문 근거: \"Some people, including many elderly people, simply have poor eyesight\" (많은 노인들을 포함한 어떤 사람들은 그저 시력이 나쁠 뿐이다)\n원문의 For this reason(이런 이유로)은 시력이 나빠 글을 읽기 어려운 사람들을 가리키는데 바꾼 문장은 그들이 '아니라' 전혀 못 보는 사람을 위해서라고 해서 달라요.\n목적 대상 바꿈: For this reason의 this가 무엇을 가리키는지 앞 문장까지 거슬러 가야 잡힘","t":"목적 대상 바꿈"}]},{"id":"j4-8","src":"본문","where":"❹ 보고 듣기에 쉬운 콘텐츠","en":"As for audio content, accessible websites allow users to adjust the volume of background sound or to turn it off altogether. This gives users both with and without hearing difficulties more control over their experience while they are using the sites.","ko":"음성 콘텐츠에 관해서는, 접근성 있는 웹 사이트는 사용자가 배경음의 음량을 조절하거나 그것을 완전히 끌 수 있게 해 준다. 이것은 청각에 어려움이 있는 사용자와 없는 사용자 모두에게 사이트를 이용하는 동안 자신의 경험을 더 잘 통제할 수 있게 해 준다.","v":[{"en":"Accessible websites let users lower the volume of background sound, though not turn it off completely.","same":false,"ko":"접근성 있는 웹 사이트는 사용자가 배경음의 음량을 낮추게는 해 주지만, 그것을 완전히 끄게 해 주지는 않는다.","diff":["or to turn it off altogether","though not turn it off completely","완전히 끌 수도 있음","완전히 끄지는 못함"],"y":"본문 근거: \"accessible websites allow users to adjust the volume of background sound or to turn it off altogether\" (접근성 있는 웹 사이트는 사용자가 배경음의 음량을 조절하거나 그것을 완전히 끌 수 있게 해 준다)\n원문은 음량 조절도 되고 '완전히 끌 수도' 있다고 했는데 바꾼 문장은 완전히 끄는 건 '안 된다'고 해서 달라요.\n일부만 맞는 문장: 앞부분(음량 조절)이 맞아서 though not 뒤의 부정을 흘려 읽기 쉬움","t":"일부만 맞는 문장"},{"en":"It is only users with hearing difficulties who get more control over their experience from this feature.","same":false,"ko":"이 기능으로 자신의 경험을 더 잘 통제하게 되는 것은 오직 청각에 어려움이 있는 사용자들뿐이다.","diff":["users both with and without hearing difficulties","only users with hearing difficulties","청각에 어려움이 있는 사용자와 없는 사용자 모두","청각에 어려움이 있는 사용자만"],"y":"본문 근거: \"This gives users both with and without hearing difficulties more control\" (이것은 청각에 어려움이 있는 사용자와 없는 사용자 모두에게 더 많은 통제권을 준다)\n원문은 청각에 어려움이 '있든 없든' 모든 사용자가 도움을 받는다고 했는데 바꾼 문장은 어려움이 있는 사용자'만'이라고 해서 범위가 좁아졌어요.\n강조구문 범위 축소: both with and without을 빠르게 읽으면 with만 기억에 남아 only 문장이 맞아 보임","t":"강조구문 범위 축소"},{"en":"On accessible websites, users can change how loud the background sound is or turn it off completely.","same":true,"ko":"접근성 있는 웹 사이트에서 사용자는 배경음의 크기를 바꾸거나 그것을 완전히 끌 수 있다.","sw":[["adjust the volume of background sound","change how loud the background sound is","배경음의 음량을 조절하다 ↔ 배경음이 얼마나 큰지를 바꾸다"],["altogether","completely","완전히 ↔ 완전히"]],"n":"allow A to do를 A can do로, 명사 volume을 how loud절로 바꿔도 같은 내용"},{"en":"Whether or not they have hearing difficulties, users gain more control over their experience on the sites.","same":true,"ko":"청각에 어려움이 있든 없든, 사용자는 사이트에서 자신의 경험을 더 잘 통제하게 된다.","sw":[["both with and without hearing difficulties","Whether or not they have hearing difficulties","청각 어려움이 있는 사람과 없는 사람 모두 ↔ 청각 어려움이 있든 없든"],["This gives users","users gain","사용자에게 준다 ↔ 사용자가 얻는다"]],"n":"both with and without = whether or not"},{"en":"Accessible websites adjust the volume of background sound automatically, so users don’t need to control their experience while using the sites.","same":false,"ko":"접근성 있는 웹 사이트는 배경음의 음량을 자동으로 조절하므로, 사용자는 사이트를 이용하는 동안 자신의 경험을 통제할 필요가 없다.","diff":["allow users to adjust the volume of background sound","adjust the volume of background sound automatically","사용자가 직접 음량을 조절하게 해 줌","웹 사이트가 알아서 음량을 조절함"],"y":"본문 근거: \"accessible websites allow users to adjust the volume of background sound\" (접근성 있는 웹 사이트는 사용자가 배경음의 음량을 조절할 수 있게 해 준다)\n원문은 '사용자가' 직접 조절하게 해서 통제권을 더 주는 건데, 바꾼 문장은 '사이트가' 알아서 조절해 사용자가 통제할 필요가 없다고 해서 달라요.\n주체 바꿈(누가 조절하나): adjust the volume of background sound가 그대로 있어 같은 말 같지만, allow users to(사용자가 ~하게 해 주다)가 사라진 걸 잡아야 함","t":"주체 바꿈(누가 조절하나)"},{"en":"Being able to control background sound benefits users who have hearing difficulties as well as those who do not.","same":true,"ko":"배경음을 조절할 수 있다는 것은 청각에 어려움이 없는 사용자뿐만 아니라 어려움이 있는 사용자에게도 도움이 된다.","sw":[["both with and without hearing difficulties","who have hearing difficulties as well as those who do not","청각 어려움이 있는 사용자와 없는 사용자 모두 ↔ 어려움이 있는 사용자도, 없는 사용자도"]],"n":"both A and B = A as well as B"}]},{"id":"j4-9","src":"본문","where":"❺ 키보드를 사용하는 완전한 탐색","en":"Some users have disabilities that limit the movement of their hands. They rely on their keyboards, rather than a mouse, to navigate websites. On accessible websites, users can access everything on the site using only a keyboard.","ko":"어떤 사용자들은 손의 움직임을 제한하는 장애를 가지고 있다. 그들은 웹 사이트를 탐색하기 위해 마우스보다는 키보드에 의존한다. 접근성 있는 웹 사이트에서는 사용자가 키보드만 사용해서 사이트의 모든 것에 접근할 수 있다.","v":[{"en":"A mouse is not needed to use everything on an accessible website.","same":true,"ko":"접근성 있는 웹 사이트의 모든 것을 이용하는 데 마우스가 필요하지 않다.","sw":[["using only a keyboard","A mouse is not needed","키보드만 사용하여 ↔ 마우스가 필요 없음"]],"n":"only a keyboard = 마우스 불필요(부정문으로 바꿔 말하기)"},{"en":"Everything on an accessible website can be reached with a keyboard alone.","same":true,"ko":"접근성 있는 웹 사이트의 모든 것은 키보드 하나만으로 접근될 수 있다.","sw":[["users can access everything on the site","Everything on an accessible website can be reached","사용자가 사이트의 모든 것에 접근할 수 있다 ↔ 사이트의 모든 것이 접근될 수 있다"],["using only a keyboard","with a keyboard alone","키보드만 사용해서 ↔ 키보드 하나만으로"]],"n":"능동태를 수동태로, only = alone"},{"en":"On accessible websites, not everything on the site can be accessed with a keyboard alone.","same":false,"ko":"접근성 있는 웹 사이트에서는 사이트의 모든 것에 키보드만으로 접근할 수 있는 것은 아니다.","diff":["users can access everything on the site using only a keyboard","not everything on the site can be accessed with a keyboard alone","키보드만으로 모든 것에 접근 가능","키보드만으로 모든 것에 접근할 수 있는 것은 아님"],"y":"본문 근거: \"users can access everything on the site using only a keyboard\" (사용자가 키보드만 사용해서 사이트의 모든 것에 접근할 수 있다)\n원문은 키보드만으로 사이트의 '모든 것'에 접근할 수 있다고 했는데 바꾼 문장은 '모든 것이 되는 건 아니다'라고 해서 달라요.\n부분부정 함정: not everything은 '일부는 안 된다'는 뜻. everything·keyboard alone이 그대로 있어 같은 말로 착각하기 쉬움","t":"부분부정 함정"},{"en":"Users whose hand movement is limited prefer a mouse to a keyboard for navigating websites.","same":false,"ko":"손의 움직임이 제한된 사용자들은 웹 사이트를 탐색할 때 키보드보다 마우스를 선호한다.","diff":["rely on their keyboards, rather than a mouse","prefer a mouse to a keyboard","마우스보다는 키보드에 의존","키보드보다 마우스를 선호"],"y":"본문 근거: \"They rely on their keyboards, rather than a mouse, to navigate websites\" (그들은 웹 사이트를 탐색하기 위해 마우스보다는 키보드에 의존한다)\n원문은 마우스보다 '키보드'에 의존한다고 했는데 바꾼 문장은 키보드보다 '마우스'를 선호한다고 해서 정반대예요.\n비교 방향 뒤집기: prefer A to B(B보다 A를 선호)와 A rather than B(B보다는 A)의 A·B 자리가 반대라 헷갈리기 쉬움","t":"비교 방향 뒤집기"},{"en":"Some users have limited hand movement because they rely on their keyboards rather than a mouse.","same":false,"ko":"어떤 사용자들은 마우스보다는 키보드에 의존하기 때문에 손의 움직임이 제한되어 있다.","diff":["Some users have disabilities that limit the movement of their hands. They rely on their keyboards","because they rely on their keyboards","손 장애 → 그래서 키보드에 의존","키보드에 의존 → 그래서 손 움직임 제한"],"y":"본문 근거: \"Some users have disabilities that limit the movement of their hands\" (어떤 사용자들은 손의 움직임을 제한하는 장애를 가지고 있다)\n원문은 손 움직임이 제한되어서 키보드에 의존하는 것인데 바꾼 문장은 키보드에 의존하기 '때문에' 손 움직임이 제한된다고 원인과 결과를 뒤집었어요.\n인과 뒤집기: 두 사실 모두 본문에 있어서 맞는 말 같지만 because가 무엇을 원인으로 삼는지 따져야 함","t":"인과 뒤집기"},{"en":"Some users whose hand movement is limited by a disability navigate websites with their keyboards instead of a mouse.","same":true,"ko":"장애 때문에 손의 움직임이 제한된 어떤 사용자들은 마우스 대신 키보드로 웹 사이트를 탐색한다.","sw":[["have disabilities that limit the movement of their hands","whose hand movement is limited by a disability","손의 움직임을 제한하는 장애가 있다 ↔ 장애로 손의 움직임이 제한된(수동태)"],["rather than a mouse","instead of a mouse","마우스보다는 ↔ 마우스 대신"],["rely on their keyboards","with their keyboards","키보드에 의존한다 ↔ 키보드로"]],"n":"rather than = instead of, 두 문장을 관계사 whose로 합쳐도 같은 내용"}]},{"id":"j4-10","src":"본문","where":"❺ 키보드를 사용하는 완전한 탐색","en":"Users navigate the websites by making use of keys such as the space bar, the arrow keys, the enter key, and the tab key. For example, they can use the tab key to jump from one part of a web page to another. Both users with disabilities and those with temporarily injured hands can benefit from this kind of navigation.","ko":"사용자는 스페이스 바, 화살표 키, 엔터 키, 탭 키 같은 키를 활용해서 웹 사이트를 탐색한다. 예를 들어, 그들은 탭 키를 사용해 웹 페이지의 한 부분에서 다른 부분으로 건너뛸 수 있다. 장애가 있는 사용자와 일시적으로 손을 다친 사용자 모두 이런 종류의 탐색으로 도움을 받을 수 있다.","v":[{"en":"Users with disabilities and those with temporarily injured hands cannot both benefit from this kind of navigation.","same":false,"ko":"장애가 있는 사용자와 일시적으로 손을 다친 사용자가 이런 종류의 탐색으로 둘 다 도움을 받을 수 있는 것은 아니다.","diff":["Both users with disabilities and those with temporarily injured hands can benefit","cannot both benefit","둘 다 도움을 받을 수 있음","둘 다 도움을 받을 수 있는 것은 아님"],"y":"본문 근거: \"Both users with disabilities and those with temporarily injured hands can benefit from this kind of navigation\" (장애가 있는 사용자와 일시적으로 손을 다친 사용자 모두 이런 종류의 탐색으로 도움을 받을 수 있다)\n원문은 두 사용자 집단 '모두' 도움을 받는다고 했는데 바꾼 문장은 '둘 다 받을 수 있는 건 아니다'(한쪽은 못 받는다)라고 해서 달라요.\n부분부정 함정(not both): cannot both는 '둘 다 ~인 것은 아니다'라는 부분부정. both가 그대로 보여서 같은 말로 착각하기 쉬움","t":"부분부정 함정(not both)"},{"en":"Keyboard navigation is helpful not only to users with disabilities but also to people whose hands are hurt for a short time.","same":true,"ko":"키보드 탐색은 장애가 있는 사용자뿐만 아니라 잠시 손을 다친 사람에게도 도움이 된다.","sw":[["Both users with disabilities and","not only to users with disabilities but also","장애가 있는 사용자와 ~ 모두 ↔ 장애가 있는 사용자뿐만 아니라 ~도"],["those with temporarily injured hands","people whose hands are hurt for a short time","일시적으로 손을 다친 사람 ↔ 잠시 손을 다친 사람"]],"n":"both A and B = not only A but also B"},{"en":"The tab key lets users move from one part of a web page to another.","same":true,"ko":"탭 키는 사용자가 웹 페이지의 한 부분에서 다른 부분으로 이동할 수 있게 해 준다.","sw":[["they can use the tab key to jump","The tab key lets users move","탭 키를 사용해 건너뛸 수 있다 ↔ 탭 키가 사용자를 이동하게 해 준다"]],"n":"사람 주어를 사물 주어(let)로 바꿔도 같은 내용"},{"en":"Users navigate with keys such as the space bar and the arrow keys, while the tab key is used only for typing.","same":false,"ko":"사용자는 스페이스 바와 화살표 키 같은 키로 탐색하는 반면, 탭 키는 오직 타자를 칠 때만 쓰인다.","diff":["they can use the tab key to jump from one part of a web page to another","the tab key is used only for typing","탭 키로 웹 페이지의 한 부분에서 다른 부분으로 건너뜀","탭 키는 타자 칠 때만 쓰임"],"y":"본문 근거: \"they can use the tab key to jump from one part of a web page to another\" (그들은 탭 키를 사용해 웹 페이지의 한 부분에서 다른 부분으로 건너뛸 수 있다)\n원문은 탭 키로 페이지 안을 '건너뛰며 탐색한다'고 했는데 바꾼 문장은 탭 키가 타자 칠 때'만' 쓰인다고 해서 달라요.\n기능 한정(only): 앞부분의 키 목록이 본문과 같아 안심하게 됨. 탭 키도 탐색 키 목록에 들어 있다는 점이 포인트","t":"기능 한정(only)"},{"en":"Users can use the tab key to jump from one part of a web page to another only if they have disabilities.","same":false,"ko":"사용자는 장애가 있을 경우에만 탭 키를 사용해 웹 페이지의 한 부분에서 다른 부분으로 건너뛸 수 있다.","diff":["Both users with disabilities and those with temporarily injured hands","only if they have disabilities","장애인과 손을 일시적으로 다친 사람 모두","장애가 있을 경우에만"],"y":"본문 근거: \"Both users with disabilities and those with temporarily injured hands can benefit from this kind of navigation\" (장애가 있는 사용자와 일시적으로 손을 다친 사용자 모두 이런 종류의 탐색으로 도움을 받을 수 있다)\n원문은 장애인뿐 아니라 일시적으로 손을 다친 사람도 이 탐색을 이용한다고 했는데 바꾼 문장은 장애가 있을 '때만' 쓸 수 있다고 조건을 좁혀서 달라요.\n필요조건 함정(only if): 앞부분이 본문 문장과 거의 똑같아서 맨 끝 only if를 놓치기 쉬움. only if는 '~일 때만'이라는 필요조건","t":"필요조건 함정(only if)"},{"en":"Keys like the space bar and the arrow keys are used to navigate the websites.","same":true,"ko":"스페이스 바와 화살표 키 같은 키들이 웹 사이트를 탐색하는 데 사용된다.","sw":[["making use of keys such as the space bar","Keys like the space bar","스페이스 바 같은 키를 활용하여 ↔ 스페이스 바 같은 키들"]],"n":"by -ing(수단)를 수동태 주어로 바꿔도 같은 내용"}]},{"id":"j4-11","src":"본문","where":"❻ 정보를 전달하는 색상 이외의 지표들","en":"Color blindness is a common visual disability. People with color blindness find it difficult to tell some colors apart. This can cause problems, especially when graphs and charts only use colors to show the differences between sets of information. Accessible websites use other indicators along with the colors.","ko":"색맹은 흔한 시각 장애이다. 색맹이 있는 사람들은 몇몇 색을 구별하기 어려워한다. 이것은 특히 그래프와 차트가 정보 집합 사이의 차이를 보여 주기 위해 색만 사용할 때 문제를 일으킬 수 있다. 접근성 있는 웹 사이트는 색과 함께 다른 지표들을 사용한다.","v":[{"en":"Instead of relying on colors alone, accessible websites add other indicators.","same":true,"ko":"접근성 있는 웹 사이트는 색에만 의존하는 대신 다른 지표들을 더한다.","sw":[["use other indicators along with the colors","add other indicators","색과 함께 다른 지표를 사용하다 ↔ 다른 지표를 더하다"]],"n":"along with the colors = 색에만 의존하지 않음"},{"en":"Graphs that show differences with colors alone can be a problem for people with color blindness.","same":true,"ko":"색만으로 차이를 보여 주는 그래프는 색맹이 있는 사람들에게 문제가 될 수 있다.","sw":[["only use colors","with colors alone","색만 사용하다 ↔ 색만으로"],["This can cause problems","can be a problem","문제를 일으킬 수 있다 ↔ 문제가 될 수 있다"]],"n":"only = alone, when 조건절을 관계절로 바꿔도 같은 내용"},{"en":"Accessible websites replace colors with other indicators.","same":false,"ko":"접근성 있는 웹 사이트는 색을 다른 지표들로 대체한다.","diff":["use other indicators along with the colors","replace colors with other indicators","색과 함께 다른 지표 사용","색을 다른 지표로 대체(색은 안 씀)"],"y":"본문 근거: \"Accessible websites use other indicators along with the colors\" (접근성 있는 웹 사이트는 색과 함께 다른 지표들을 사용한다)\n원문은 색과 '함께' 다른 지표를 쓴다고 했는데 바꾼 문장은 색을 다른 지표로 '대체한다'(색을 안 쓴다)고 해서 달라요.\n함께↔대신 바꿔치기: replace A with B는 'A를 B로 바꾼다'는 뜻. other indicators가 그대로 있어 같은 말로 보이기 쉬움","t":"함께↔대신 바꿔치기"},{"en":"Problems arise mainly when graphs and charts use other indicators as well as colors.","same":false,"ko":"문제는 주로 그래프와 차트가 색뿐만 아니라 다른 지표들도 함께 사용할 때 생긴다.","diff":["especially when graphs and charts only use colors","mainly when graphs and charts use other indicators as well as colors","특히 색만 사용할 때 문제","주로 다른 지표도 함께 쓸 때 문제"],"y":"본문 근거: \"This can cause problems, especially when graphs and charts only use colors to show the differences\" (이것은 특히 그래프와 차트가 차이를 보여 주기 위해 색만 사용할 때 문제를 일으킬 수 있다)\n원문은 그래프가 색'만' 쓸 때 문제가 생긴다고 했는데 바꾼 문장은 다른 지표도 '함께' 쓸 때 문제가 생긴다고 해서 조건이 뒤집혔어요.\n조건 뒤집기: especially when과 mainly when이 비슷해서 그 뒤의 조건(only vs as well as)을 확인하지 않으면 속음","t":"조건 뒤집기"},{"en":"It is hard for people with color blindness to distinguish between some colors.","same":true,"ko":"색맹이 있는 사람들은 몇몇 색을 구별하기가 어렵다.","sw":[["find it difficult","It is hard","어려워하다 ↔ 어렵다"],["tell some colors apart","distinguish between some colors","몇몇 색을 구별하다 ↔ 몇몇 색을 구별하다"]],"n":"find it difficult to = It is hard for ~ to"},{"en":"People with color blindness find it difficult to tell any two colors apart.","same":false,"ko":"색맹이 있는 사람들은 어떤 두 색이든 구별하기 어려워한다.","diff":["some colors","any two colors","몇몇 색","어떤 두 색이든(모든 색)"],"y":"본문 근거: \"People with color blindness find it difficult to tell some colors apart\" (색맹이 있는 사람들은 몇몇 색을 구별하기 어려워한다)\n원문은 '몇몇' 색을 구별하기 어렵다고 했는데 바꾼 문장은 '어떤 두 색이든' 구별하기 어렵다고 해서 모든 색으로 범위가 넓어졌어요.\n범위 과장: 나머지 표현이 원문과 똑같아 any가 '모든'을 뜻한다는 점을 놓치기 쉬움","t":"범위 과장"}]},{"id":"j4-12","src":"본문","where":"❻ 정보를 전달하는 색상 이외의 지표들","en":"The accessibility features of websites don’t just help people with disabilities. They can make online experiences easier for everyone, regardless of abilities or situations. When websites are easy to navigate and understand, we can all benefit from a more inclusive online experience.","ko":"웹 사이트의 접근성 기능은 장애가 있는 사람들만 돕는 것이 아니다. 그것들은 능력이나 상황에 관계없이 모든 사람의 온라인 경험을 더 쉽게 만들 수 있다. 웹 사이트가 탐색하고 이해하기 쉬우면, 우리 모두가 더 포용적인 온라인 경험의 혜택을 누릴 수 있다.","v":[{"en":"No matter what their abilities or situations are, all users can have easier online experiences thanks to accessibility features.","same":true,"ko":"능력이나 상황이 어떻든, 모든 사용자는 접근성 기능 덕분에 더 쉬운 온라인 경험을 할 수 있다.","sw":[["regardless of abilities or situations","No matter what their abilities or situations are","능력이나 상황에 관계없이 ↔ 능력이나 상황이 무엇이든"],["make online experiences easier for everyone","all users can have easier online experiences","모두의 온라인 경험을 더 쉽게 만들다 ↔ 모든 사용자가 더 쉬운 온라인 경험을 하다"]],"n":"regardless of = no matter what"},{"en":"Accessibility features help not only people with disabilities but also everyone else.","same":true,"ko":"접근성 기능은 장애가 있는 사람들뿐만 아니라 다른 모든 사람도 돕는다.","sw":[["don’t just help people with disabilities","help not only people with disabilities","장애인만 돕는 것이 아니다 ↔ 장애인뿐만 아니라 돕는다"]],"n":"not just A = not only A but also B"},{"en":"It is just people with disabilities that the accessibility features of websites help.","same":false,"ko":"웹 사이트의 접근성 기능이 돕는 것은 단지 장애가 있는 사람들뿐이다.","diff":["don’t just help people with disabilities","It is just people with disabilities","장애인만 돕는 것이 아님","장애인만 도움"],"y":"본문 근거: \"The accessibility features of websites don’t just help people with disabilities\" (웹 사이트의 접근성 기능은 장애가 있는 사람들만 돕는 것이 아니다)\n원문은 장애인'만' 돕는 게 '아니라'고 했는데 바꾼 문장은 강조구문으로 장애인'만' 돕는다고 해서 정반대예요.\n강조구문 부정 빠뜨리기: just·people with disabilities·help가 모두 원문에 있어서 don’t 하나가 빠진 것을 놓치기 쉬움","t":"강조구문 부정 빠뜨리기"},{"en":"If a website is easy to use and understand, everyone can enjoy a more inclusive online experience.","same":true,"ko":"웹 사이트가 사용하고 이해하기 쉬우면, 모든 사람이 더 포용적인 온라인 경험을 누릴 수 있다.","sw":[["When websites are easy to navigate and understand","If a website is easy to use and understand","웹 사이트가 탐색하고 이해하기 쉬울 때 ↔ 웹 사이트가 사용하고 이해하기 쉬우면"],["we can all benefit from","everyone can enjoy","우리 모두 혜택을 누릴 수 있다 ↔ 모든 사람이 누릴 수 있다"]],"n":"When 조건 = If, we all = everyone"},{"en":"Websites become easy to navigate and understand only after we all benefit from a more inclusive online experience.","same":false,"ko":"웹 사이트는 우리 모두가 더 포용적인 온라인 경험의 혜택을 누린 후에야 탐색하고 이해하기 쉬워진다.","diff":["When websites are easy to navigate and understand, we can all benefit","only after we all benefit","사이트가 쉬우면 → 우리 모두 혜택","우리 모두 혜택을 누린 후에야 → 사이트가 쉬워짐"],"y":"본문 근거: \"When websites are easy to navigate and understand, we can all benefit from a more inclusive online experience\" (웹 사이트가 탐색하고 이해하기 쉬우면, 우리 모두가 더 포용적인 온라인 경험의 혜택을 누릴 수 있다)\n원문은 사이트가 쉬우면 '그 결과' 우리 모두 혜택을 누린다고 했는데 바꾼 문장은 혜택을 누린 '후에야' 사이트가 쉬워진다고 선후를 뒤집었어요.\n선후·인과 뒤집기: only after(~한 뒤에야)가 순서를 바꿔 놓음. 같은 어휘로 앞뒤만 바꿔서 읽기만 하면 맞아 보임","t":"선후·인과 뒤집기"},{"en":"Accessibility features make online experiences easier only for people with certain abilities or in certain situations.","same":false,"ko":"접근성 기능은 특정 능력을 가졌거나 특정 상황에 있는 사람들에게만 온라인 경험을 더 쉽게 만든다.","diff":["for everyone, regardless of abilities or situations","only for people with certain abilities or in certain situations","능력이나 상황에 관계없이 모든 사람","특정 능력·상황의 사람들만"],"y":"본문 근거: \"They can make online experiences easier for everyone, regardless of abilities or situations\" (그것들은 능력이나 상황에 관계없이 모든 사람의 온라인 경험을 더 쉽게 만들 수 있다)\n원문은 능력이나 상황에 '관계없이' 모든 사람에게 쉽다고 했는데 바꾼 문장은 특정 능력·상황의 사람들'만'이라고 해서 달라요.\n범위 축소: abilities·situations가 그대로 나와 같은 말 같지만 regardless of(~에 관계없이)가 only for로 바뀐 게 핵심","t":"범위 축소"}]},{"id":"j4-13","src":"본문","where":"❼ 웹을 더 문화적으로 접근 가능하게 만들기","en":"Reading and writing systems are different across cultures. People from Western cultures read and write from left to right, while those from some Middle Eastern cultures read and write from right to left. People from some Eastern cultures, like that of Japan, read and write from top to bottom. Some global websites take these differences into consideration and adjust their websites for people in different regions.","ko":"읽기와 쓰기 체계는 문화마다 다르다. 서양 문화권 사람들은 왼쪽에서 오른쪽으로 읽고 쓰는 반면, 일부 중동 문화권 사람들은 오른쪽에서 왼쪽으로 읽고 쓴다. 일본 문화처럼 일부 동양 문화권 사람들은 위에서 아래로 읽고 쓴다. 몇몇 세계적인 웹 사이트는 이러한 차이를 고려해서 다른 지역의 사람들에 맞게 웹 사이트를 조정한다.","v":[{"en":"In Japanese culture, people read and write from top to bottom.","same":true,"ko":"일본 문화에서는 사람들이 위에서 아래로 읽고 쓴다.","sw":[["like that of Japan","In Japanese culture","일본 문화처럼 ↔ 일본 문화에서는"]],"n":"예시(like that of Japan)를 문장의 중심으로 끌어내도 같은 내용"},{"en":"Some global websites take these differences into consideration but expect people in different regions to adapt to their websites.","same":false,"ko":"몇몇 세계적인 웹 사이트는 이러한 차이를 고려하지만, 다른 지역의 사람들이 자신들의 웹 사이트에 적응하기를 기대한다.","diff":["adjust their websites for people in different regions","expect people in different regions to adapt to their websites","웹 사이트가 사람들에게 맞춤","사람들이 웹 사이트에 맞춤"],"y":"본문 근거: \"Some global websites take these differences into consideration and adjust their websites for people in different regions\" (몇몇 세계적인 웹 사이트는 이러한 차이를 고려해서 다른 지역의 사람들에 맞게 웹 사이트를 조정한다)\n원문은 '웹 사이트가' 지역 사람들에게 맞춰 바꾼다는 건데, 바꾼 문장은 '사람들이' 웹 사이트에 적응하길 바란다고 해서 방향이 반대예요.\n주체·대상 바꿈(누가 누구에게 맞추나): take these differences into consideration, people in different regions가 그대로라 같은 말 같지만, 누가 맞춰 주는지를 따져야 함","t":"주체·대상 바꿈(누가 누구에게 맞추나)"},{"en":"Some global websites consider cultural differences in reading and writing and change their designs for users in different regions.","same":true,"ko":"몇몇 세계적인 웹 사이트는 읽기와 쓰기의 문화적 차이를 고려해 다른 지역의 사용자에 맞게 디자인을 바꾼다.","sw":[["take these differences into consideration","consider cultural differences","이러한 차이를 고려하다 ↔ 문화적 차이를 고려하다"],["adjust their websites","change their designs","웹 사이트를 조정하다 ↔ 디자인을 바꾸다"]],"n":"take ~ into consideration = consider"},{"en":"Reading and writing systems differ across cultures because some global websites adjust their websites for people in different regions.","same":false,"ko":"몇몇 세계적인 웹 사이트가 다른 지역의 사람들에 맞게 웹 사이트를 조정하기 때문에 읽기와 쓰기 체계가 문화마다 다르다.","diff":["Some global websites take these differences into consideration and adjust","because some global websites adjust","문화 차이 → 그래서 웹 사이트가 조정","웹 사이트 조정 → 그래서 문화 차이"],"y":"본문 근거: \"Some global websites take these differences into consideration and adjust their websites\" (몇몇 세계적인 웹 사이트는 이러한 차이를 고려해서 웹 사이트를 조정한다)\n원문은 문화마다 읽기·쓰기가 달라서 웹 사이트가 그 차이를 '고려해' 조정한다고 했는데 바꾼 문장은 웹 사이트가 조정하기 '때문에' 문화마다 다르다고 원인과 결과를 뒤집었어요.\n인과 뒤집기: 두 사실이 모두 본문에 있어 맞는 말 같지만 take ~ into consideration(~을 고려하다)이 원인을 알려 줌","t":"인과 뒤집기"},{"en":"Unlike people from Western cultures, people from some Middle Eastern cultures read and write from right to left.","same":true,"ko":"서양 문화권 사람들과 달리, 일부 중동 문화권 사람들은 오른쪽에서 왼쪽으로 읽고 쓴다.","sw":[["while those from some Middle Eastern cultures","Unlike people from Western cultures","~인 반면 일부 중동 문화권 사람들은 ↔ 서양 문화권 사람들과 달리"]],"n":"while 대조를 Unlike 전치사구로 바꿔도 같은 내용"},{"en":"It is only in Western cultures that people read and write horizontally.","same":false,"ko":"사람들이 가로로 읽고 쓰는 것은 오직 서양 문화권에서뿐이다.","diff":["those from some Middle Eastern cultures read and write from right to left","only in Western cultures","일부 중동 문화권도 (오른쪽에서 왼쪽으로) 가로로 읽고 씀","서양 문화권에서만 가로로 읽고 씀"],"y":"본문 근거: \"those from some Middle Eastern cultures read and write from right to left\" (일부 중동 문화권 사람들은 오른쪽에서 왼쪽으로 읽고 쓴다)\n원문에서 중동 문화권도 오른쪽에서 왼쪽으로, 즉 가로로 읽고 쓰는데 바꾼 문장은 가로 읽기가 서양'만'이라고 해서 달라요.\n강조구문 범위 한정: horizontally(가로로)가 left to right와 right to left를 모두 포함한다는 걸 추론해야 잡히는 함정","t":"강조구문 범위 한정"}]},{"id":"j4-14","src":"본문","where":"❼ 웹을 더 문화적으로 접근 가능하게 만들기","en":"In countries where text is read from right to left, the website’s search button is on the left and the logo is on the right. If you visit the same websites in a different language setting, you will see a different format.","ko":"글을 오른쪽에서 왼쪽으로 읽는 나라에서는 웹 사이트의 검색 버튼이 왼쪽에, 로고가 오른쪽에 있다. 같은 웹 사이트를 다른 언어 설정으로 방문하면, 다른 형식을 보게 될 것이다.","v":[{"en":"In countries where text is read from right to left, the website’s search button stays on the left whatever language setting you use.","same":false,"ko":"글을 오른쪽에서 왼쪽으로 읽는 나라에서는 어떤 언어 설정을 쓰든 웹 사이트의 검색 버튼이 왼쪽에 그대로 있다.","diff":["If you visit the same websites in a different language setting, you will see a different format","stays on the left whatever language setting you use","언어 설정이 다르면 다른 형식이 보임","언어 설정과 상관없이 검색 버튼이 왼쪽에 그대로 있음"],"y":"본문 근거: \"If you visit the same websites in a different language setting, you will see a different format\" (같은 웹 사이트를 다른 언어 설정으로 방문하면, 다른 형식을 보게 될 것이다)\n원문은 언어 설정이 바뀌면 형식도 바뀐다고 했는데, 바꾼 문장은 어떤 언어 설정이든 검색 버튼이 '그대로' 왼쪽이라고 해서 달라요.\n조건 무시(양보 whatever): 앞부분(오른쪽→왼쪽 읽는 나라, 검색 버튼 왼쪽)이 첫 문장과 똑같아 맞는 말 같지만, 뒤의 whatever(~이든 상관없이)가 둘째 문장과 부딪힘","t":"조건 무시(양보 whatever)"},{"en":"In countries where text is read from right to left, the logo is on the left, while the search button is on the right.","same":false,"ko":"글을 오른쪽에서 왼쪽으로 읽는 나라에서는 로고가 왼쪽에 있는 반면, 검색 버튼은 오른쪽에 있다.","diff":["the website’s search button is on the left and the logo is on the right","the logo is on the left, while the search button is on the right","검색 버튼 왼쪽, 로고 오른쪽","로고 왼쪽, 검색 버튼 오른쪽"],"y":"본문 근거: \"the website’s search button is on the left and the logo is on the right\" (웹 사이트의 검색 버튼이 왼쪽에, 로고가 오른쪽에 있다)\n원문은 검색 버튼이 왼쪽, 로고가 오른쪽인데 바꾼 문장은 로고가 왼쪽, 검색 버튼이 오른쪽이라고 위치를 맞바꿨어요.\n위치 맞바꾸기: left·right가 둘 다 나오고 주어 순서까지 바뀌어서 짝을 하나씩 맞춰 봐야 잡힘","t":"위치 맞바꾸기"},{"en":"Only if you visit a different website will you see a different format.","same":false,"ko":"다른 웹 사이트를 방문할 경우에만 다른 형식을 보게 될 것이다.","diff":["If you visit the same websites in a different language setting","Only if you visit a different website","같은 사이트라도 언어 설정이 다르면","다른 사이트를 방문할 때만"],"y":"본문 근거: \"If you visit the same websites in a different language setting, you will see a different format\" (같은 웹 사이트를 다른 언어 설정으로 방문하면, 다른 형식을 보게 될 것이다)\n원문은 '같은' 사이트도 언어 설정만 다르면 다른 형식이 보인다고 했는데 바꾼 문장은 '다른' 사이트를 방문할 때만 다른 형식이 보인다고 해서 달라요.\nOnly if 도치(필요조건): Only if 도치(will you see)가 문장을 낯설게 만들어 조건이 바뀐 걸 놓치기 쉬움. only if는 '~일 때만'","t":"Only if 도치(필요조건)"},{"en":"Changing the language setting of the same website will show you a different format.","same":true,"ko":"같은 웹 사이트의 언어 설정을 바꾸면 다른 형식이 보일 것이다.","sw":[["If you visit the same websites in a different language setting","Changing the language setting of the same website","같은 사이트를 다른 언어 설정으로 방문하면 ↔ 같은 사이트의 언어 설정을 바꾸는 것"]],"n":"If 조건절을 동명사 주어로 바꿔도 같은 내용"},{"en":"Where people read text from right to left, the logo is placed on the right and the search button on the left.","same":true,"ko":"사람들이 글을 오른쪽에서 왼쪽으로 읽는 곳에서는 로고가 오른쪽에, 검색 버튼이 왼쪽에 놓인다.","sw":[["text is read from right to left","people read text from right to left","글이 오른쪽에서 왼쪽으로 읽히다 ↔ 사람들이 글을 오른쪽에서 왼쪽으로 읽다"],["the logo is on the right","the logo is placed on the right","로고가 오른쪽에 있다 ↔ 로고가 오른쪽에 놓인다"]],"n":"수동태를 능동태로 바꾸고 두 항목 순서를 바꿔도 같은 내용"},{"en":"The format of a website can look different depending on its language setting.","same":true,"ko":"웹 사이트의 형식은 언어 설정에 따라 다르게 보일 수 있다.","sw":[["you will see a different format","The format of a website can look different","다른 형식을 보게 될 것이다 ↔ 웹 사이트의 형식이 다르게 보일 수 있다"],["in a different language setting","depending on its language setting","다른 언어 설정으로 ↔ 언어 설정에 따라"]],"n":"사람 주어를 사물 주어로 바꿔 요약해도 같은 내용"}]}];
